40	/// for a Zombie creature spell cast by the given player.
41	fn rooftop_storm_applies(state: &GameState, registry: &CardRegistry, card_id: CardId, caster: PlayerId) -> bool {
42	    // Check if the spell is a Zombie creature spell.
43	    let is_zombie_creature = registry.card_data(card_id).map(|d| {
44	        d.card_types.contains(&CardType::Creature)
45	            && d.subtypes.iter().any(|s| s == "Zombie")
46	    }).unwrap_or(false);
47	    if !is_zombie_creature {
48	        return false;
49	    }
