                        let mut acts: Vec<Action> = options.iter()
                            .map(|t| Action::ResolveChoice { choice: ResolvedChoice::ChosenTarget(Some(t.clone())) })
                            .collect();
                        if *optional {
                            acts.push(Action::ResolveChoice { choice: ResolvedChoice::ChosenTarget(None) });

